// Um .d.ts so tem assinaturas: zero implementacao, zero valores atribuidos.
declare function somarPreco(a: number, b: number): number;

// O compilador aceita a chamada porque o TIPO bate certo...
function calcularTotal(): number {
  return somarPreco(10, 5);
}

// ...mas sem nenhum .js real por perto com o corpo de somarPreco, chamar isto
// em runtime falha: "declare" nao gera nenhum codigo executavel.
try {
  console.log(calcularTotal());
} catch (erro) {
  console.log("falhou em runtime: " + (erro as Error).message);
}
// falhou em runtime: somarPreco is not defined

// biblioteca-datas.d.ts
declare module "biblioteca-datas-sem-tipos" {
  export function formatarData(data: Date, padrao: string): string;
}

// noutro ficheiro main.ts
import { formatarData } from "biblioteca-datas-sem-tipos";

const resultado = formatarData(new Date(2024, 0, 1), "yyyy-MM-dd");
console.log(typeof resultado);

// @ts-expect-error formatarData espera um Date como primeiro argumento, nao uma string
formatarData("2024-01-01", "yyyy-MM-dd");

export {};

declare global {
  interface Window {
    versaoDaApp: string;
  }

  var contadorDeCliques: number;
}

function lerVersao(w: Window): string {
  return w.versaoDaApp;
}

globalThis.contadorDeCliques = 0;
globalThis.contadorDeCliques += 1;

console.log(typeof lerVersao);
console.log(globalThis.contadorDeCliques);
// function
// 1

export {};

// Simula uma biblioteca de formatacao sem tipos, carregada globalmente (por
// exemplo via <script src="formatador.js">), sem nenhum pacote de @types disponivel.
declare global {
  function formatarPreco(valorCentimos: number, moeda: string): string;
}

function etiquetaDoProduto(precoCentimos: number): string {
  return formatarPreco(precoCentimos, "EUR");
}

function chamadaComTipoErrado(): string {
  // @ts-expect-error formatarPreco espera o preco em centimos (number), nao uma string
  return formatarPreco("19.99", "EUR");
}

console.log(typeof etiquetaDoProduto, typeof chamadaComTipoErrado);
// function function

