// biblioteca-slugs.d.ts
declare module "biblioteca-slugs" {
  export function slugify(texto: string): string;
}

// noutro ficheiro main.ts
import { slugify } from "biblioteca-slugs";

const resultado = slugify("Titulo Do Artigo");
console.log(typeof resultado);
// string

export {};

declare global {
  interface Window {
    temaEscuro: boolean;
  }
}

function tituloDoTema(w: Window): string {
  return w.temaEscuro ? "Tema escuro ativo" : "Tema claro ativo";
}

const janelaSimulada = { temaEscuro: true } as unknown as Window;
console.log(tituloDoTema(janelaSimulada));
// Tema escuro ativo

export {};

declare global {
  function validarEmail(email: string): boolean;
}

function contarValidos(emails: string[]): number {
  return emails.filter((email) => validarEmail(email)).length;
}

function chamadaInvalida(): boolean {
  // @ts-expect-error validarEmail espera uma string, nao um number
  return validarEmail(123);
}

console.log(typeof contarValidos, typeof chamadaInvalida);
// function function
